// Finite tags MUST NOT be reused/re-enabled until old slots and commits drain.
module genefer_stream27_mdc_commutator_slots_v2 #(
    parameter int unsigned DATA_W = 27,
    parameter int unsigned PAYLOAD_W = 16,
