    initial begin
        if (PERIOD < 1 || (PERIOD & (PERIOD-1)) != 0)
            $fatal(1, "FIELD_ROOT_PERIOD");
        if (PERIOD > 1 && HEX_FILE == "") $fatal(1, "FIELD_ROOT_ROM_MISSING");
    end
    // synthesis translate_on
endmodule

