        .clk,.rst_n,.in_valid,.digit(magnitude_digit),
        .payload_in({correction[31],payload_in}),
        .out_valid(magnitude_valid),.out_error(magnitude_error),
        .residue(magnitude_residue),.payload_out(magnitude_payload)
    );
