module genefer_stream27_epoch_protocol_v5 #(
    parameter int unsigned ROWS=8192,
    parameter int unsigned POINTWISE_FIRST=8308,
    parameter int unsigned SINK_FIRST=16618,
    parameter int unsigned EPOCH_W=16
