        genefer_ntt_difdit_butterfly27 #(.P(MODULUS),.Q(Q)) butterfly (
            .clk,.rst_n,.in_valid(issue),.dif(1'b1),
            .u(u[unit_index]),.v(v[unit_index]),.w(w[unit_index]),
            .out_valid(valid[unit_index]),.y0(y0[unit_index]),.y1(y1[unit_index]));
