 initial if(PAIRS<1 || DEPTH<1 || (DEPTH&(DEPTH-1))!=0 || FRAME_T<2*DEPTH ||
  FRAME_T%(2*DEPTH)!=0 || DATA_W<1 || PAYLOAD_W<1 || GEN_W<1 ||
  (CONTEXTS!=1 && CONTEXTS!=2))$fatal(1,"SHARED_COMM_PARAMETERS");
 // synthesis translate_on
endmodule

