files.genefer_stream27_square_p16_f2_v1_contex:
// Canonical 27x27 pointwise square only, accepted k -> output k+3.
module genefer_stream27_square_p16_f2_v1_contexts_v1 #(parameter int GEN_W=8) (
 input logic clk,rst_n,in_slot_valid,frame_start,quarantine,
 input logic [GEN_W-1:0] generation_in,input logic [431:0] data_in,
 output logic out_slot_valid,out_frame_start,out_error,fault_pending,
 output logic [GEN_W-1:0] generation_out,output logic [431:0] data_out);
 logic [15:0] lane_valid;logic [3:0] slot_pipe,start_pipe;
 logic [GEN_W-1:0] generation_pipe[0:3];
 wire mismatch=lane_valid!={16{slot_pipe[3]}};
 assign fault_pending=out_error || (!quarantine && mismatch);
 assign out_slot_valid=slot_pipe[3] && (&lane_valid) && !quarantine && !out_error;
 assign out_frame_start=start_pipe[3] && out_slot_valid;assign generation_out=generation_pipe[3];
 for(genvar lane=0;lane<16;lane=lane+1)begin: square_lane
  wire [31:0] result;
  genefer_stream27_montgomery_factored_v1 #(.P(32'd67239937),.Q(32'd4227727361)) multiplier (
   .clk,.rst_n,.in_valid(in_slot_valid && !quarantine),
   .lhs({5'b0,data_in[lane*27+:27]}),.rhs({5'b0,data_in[lane*27+:27]}),
   .out_valid(lane_valid[lane]),.result(result));
  assign data_out[lane*27+:27]=result[26:0];
 end
 always_ff @(posedge clk or negedge rst_n)begin
  if(!rst_n)begin slot_pipe<=0;start_pipe<=0;out_error<=0;end
  else begin
   if(!quarantine && mismatch)out_error<=1;
   if(quarantine || out_error)begin slot_pipe<=0;start_pipe<=0;end
   else begin
    slot_pipe<={slot_pipe[2:0],in_slot_valid};start_pipe<={start_pipe[2:0],in_slot_valid && frame_start};
    generation_pipe[0]<=generation_in;
    for(int k=1;k<4;k=k+1)generation_pipe[k]<=generation_pipe[k-1];
   end
  end
 end
endmodule

files.genefer_crt3_27_mont_pipe.sv:
// Isolated Montgomery-constant CRT27 candidate; ordinary canonical residues.
// II=1,16 stages: accepted edge k -> output edge k+15 (frozen CRT: k+60).
// Raw input capture isolates the memory-output path from the modular subtracts.
// No whole-core substitution, measured resource or timing benefit is implied.
module genefer_crt3_27_mont_pipe (
    input logic clk,rst_n,in_valid,
    input logic [31:0] r1,r2,r3,
    output logic ready,out_valid,
    output logic signed [95:0] coefficient
);
    localparam logic [26:0] P1=27'd104857601,P2=27'd69206017,P3=27'd67239937;
    localparam logic [31:0] C2=32'd12212947;
    localparam logic [31:0] CA=32'd28766354;
    localparam logic [31:0] CB=32'd62755090;
    localparam logic [52:0] P12=53'd7256776917385217;
    localparam logic [78:0] MODULUS=79'd487945222748036195811329;
    logic [14:0] valid_pipe;
    logic [26:0] r2_input,r3_input,r2_d,r3_d,r1_mod2,r1_mod3,delta2;
    logic [26:0] r1_pipe[0:6],d3_pipe[0:4];
    wire [27:0] delta2_diff={1'b0,r2_d}-{1'b0,r1_mod2};
    wire [27:0] delta3_diff={1'b0,r3_d}-{1'b0,r1_mod3};
    wire [27:0] delta2_work=delta2_diff[27] ? delta2_diff+{1'b0,P2} : delta2_diff;
    wire [27:0] delta3_work=delta3_diff[27] ? delta3_diff+{1'b0,P3} : delta3_diff;
    logic v2,va3,vb3;
    logic [31:0] t2,a3,b3;
    wire [26:0] t2_mod3=t2[26:0]>=P3 ? t2[26:0]-P3 : t2[26:0];
    logic [27:0] t3_sum;
    wire [27:0] t3_work=t3_sum>={1'b0,P3} ? t3_sum-{1'b0,P3} : t3_sum;
    logic [26:0] t3;

    // Plain27x27 and53x27 products; never split into16-bit halves.
    logic [53:0] p1_t2;
    logic [26:0] r1_d;
    wire [53:0] x12_work=p1_t2+{27'b0,r1_d};
    logic [52:0] x12_pipe[0:5];
    logic [79:0] p12_t3;
    wire [79:0] value_work=p12_t3+{27'b0,x12_pipe[5]};
    logic [78:0] value;
    wire signed [95:0] centered_work=value>(MODULUS>>1) ?
        $signed({17'b0,value})-$signed({17'b0,MODULUS}) : $signed({17'b0,value});

    assign ready=1'b1;
    // Mont(a,C)=a*C*2^-32 modP. Constants below encode ordinary multipliers.
    // C2=P1^-1*2^32 modP2. Input k+3, output k+6.
    genefer_montgomery_mul27_sparse_pipe #(.P(32'(P2)),.Q(32'd2-32'(P2))) mont_t2 (
        .clk,.rst_n,.in_valid(valid_pipe[2]),.lhs({5'b0,delta2}),.rhs(C2),
        .out_valid(v2),.result(t2)
    );
    // CA=(P1*P2)^-1*2^32 modP3. Both P3 helpers: input k+7, output k+10.
    genefer_montgomery_mul27_sparse_pipe #(.P(32'(P3)),.Q(32'd2-32'(P3))) mont_a3 (
        .clk,.rst_n,.in_valid(valid_pipe[6]),.lhs({5'b0,d3_pipe[4]}),.rhs(CA),
        .out_valid(va3),.result(a3)
    );
    // CB=-P2^-1*2^32 modP3.
    genefer_montgomery_mul27_sparse_pipe #(.P(32'(P3)),.Q(32'd2-32'(P3))) mont_b3 (
        .clk,.rst_n,.in_valid(valid_pipe[6]),.lhs({5'b0,t2_mod3}),.rhs(CB),
        .out_valid(vb3),.result(b3)
    );

    // Valid-only local reset, like the frozen CRT: payload is unreset and
    // unconditionally advances; flushed validity quarantines all stale values.
    always_ff @(posedge clk)begin
        // k: capture only raw canonical low27 bits; full32-bit guard is below.
        r1_pipe[0]<=r1[26:0];r2_input<=r2[26:0];r3_input<=r3[26:0];
        for(int i=1;i<=6;i=i+1)r1_pipe[i]<=r1_pipe[i-1];
        // k+1: P1<2*P2 and2*P3, so each reduction is one subtraction.
        r1_mod2<=r1_pipe[0]>=P2 ? r1_pipe[0]-P2 : r1_pipe[0];
        r1_mod3<=r1_pipe[0]>=P3 ? r1_pipe[0]-P3 : r1_pipe[0];
        r2_d<=r2_input;r3_d<=r3_input;
        // k+2: signed28-bit differences plus modulus on borrow.
        delta2<=delta2_work[26:0];d3_pipe[0]<=delta3_work[26:0];
        for(int i=1;i<=4;i=i+1)d3_pipe[i]<=d3_pipe[i-1];

        // k+7: reconstruct x12 in parallel with the two P3 helpers.
        p1_t2<=P1*t2[26:0];r1_d<=r1_pipe[6];
        // k+8 x12, then short register delay through k+13.
        x12_pipe[0]<=x12_work[52:0];
        for(int i=1;i<=5;i=i+1)x12_pipe[i]<=x12_pipe[i-1];
        // k+11 sum is below2*P3; k+12 correction yields canonical t3.
        t3_sum<={1'b0,a3[26:0]}+{1'b0,b3[26:0]};
        t3<=t3_work[26:0];
        // k+13 full product; k+14 reconstructed value in [0,M).
        p12_t3<=P12*t3;
        value<=value_work[78:0];
    end
    always_ff @(posedge clk or negedge rst_n)begin
        if(!rst_n)begin valid_pipe<=0;out_valid<=0;coefficient<=0;end
        else begin
            valid_pipe<={valid_pipe[13:0],in_valid};
            out_valid<=valid_pipe[14];
            // k+15: strict centering rule and invalid-cycle output hold.
            if(valid_pipe[14])coefficient<=centered_work;
        end
    end
    // synthesis translate_off
    // CRT27_CONSTANT_CHECK_BEGIN
    initial begin
        if(P12!=53'(96'(P1)*96'(P2)) ||
           MODULUS!=79'(96'(P1)*96'(P2)*96'(P3)))
            $fatal(1,"CRT27 product constants");
        if(C2>=32'(P2) || CA>=32'(P3) || CB>=32'(P3) ||
           (96'(C2)*96'(P1))%96'(P2)!=96'd4294967296%96'(P2) ||
           (96'(CA)*96'(P12))%96'(P3)!=96'd4294967296%96'(P3) ||
           (96'(CB)*96'(P2))%96'(P3)!=(96'(P3)-(96'd4294967296%96'(P3))))
            $fatal(1,"CRT27 Montgomery constants");
        if(28'(P1)>=28'(P2)*28'd2 || 28'(P1)>=28'(P3)*28'd2 ||
           28'(P2)>=28'(P3)*28'd2)
            $fatal(1,"CRT27 one-subtraction preconditions");
    end
    // CRT27_CONSTANT_CHECK_END
    always @(posedge clk)if(rst_n)begin
        if(in_valid && (r1>=32'(P1) || r2>=32'(P2) || r3>=32'(P3)))$fatal(1,"noncanonical CRT27 input");
        if(v2!==valid_pipe[6] || va3!==valid_pipe[10] || vb3!==valid_pipe[10])$fatal(1,"CRT27 Montgomery valid alignment");
        if(valid_pipe[1] && delta2_work>={1'b0,P2})$fatal(1,"CRT27 delta2 bound");
        if(valid_pipe[1] && delta3_work>={1'b0,P3})$fatal(1,"CRT27 delta3 bound");
        if(v2 && t2>=32'(P2))$fatal(1,"CRT27 t2 bound");
        if(v2 && t2_mod3>=P3)$fatal(1,"CRT27 t2_mod3 bound");
        if(valid_pipe[7] && (x12_work[53] || x12_work>=54'(P12)))$fatal(1,"CRT27 x12 bound");
        if(va3 && (a3>=32'(P3) || b3>=32'(P3)))$fatal(1,"CRT27 P3 result bound");
        if(valid_pipe[11] && t3_work>={1'b0,P3})$fatal(1,"CRT27 t3 bound");
        if(valid_pipe[13] && (value_work[79] || value_work>=80'(MODULUS)))$fatal(1,"CRT27 value bound");
    end
    // synthesis translate_on
endmodule

files.genefer_montgomery_mul27_sparse_pipe.sv:
// Experimental four-stage Montgomery multiplier, II=1.
// P1=1+2^26+2^25+2^22; P2=1+2^26+2^21; P3=1+2^26+2^17.
// Only those three moduli; canonical lhs,rhs<P.
// Since (P-1)^2 is divisible by 2^32, Q=P^-1=2-P (mod 2^32).
// Reduction uses explicit shifts/adds; the only variable product is 27x27.
// Same edge k -> edge k+3 output contract as the frozen generic helper.
module genefer_montgomery_mul27_sparse_pipe #(
    parameter logic [31:0] P=32'd104857601,
    parameter logic [31:0] Q=32'd4190109697
) (
    input logic clk,rst_n,in_valid,
    input logic [31:0] lhs,rhs,
    output logic out_valid,
    output logic [31:0] result
);
    localparam integer S=(P==32'd104857601)?25:
                         (P==32'd69206017)?21:17;
    wire [26:0] lhs27=lhs[26:0],rhs27=rhs[26:0];
    logic [2:0] valid_pipe;
    logic [53:0] ab_s1;
    logic [31:0] m_s2,hi_s2,hi_s3;
    logic [58:0] mp_s3;
    wire [31:0] lo=ab_s1[31:0];
    wire [58:0] m_ext={27'b0,m_s2};
    wire [31:0] extra_q=(P==32'd104857601)?(lo<<22):32'b0;
    wire [58:0] extra_p=(P==32'd104857601)?(m_ext<<22):59'b0;
    wire [31:0] mp_hi={5'b0,mp_s3[58:32]};
    always_ff @(posedge clk or negedge rst_n)begin
        if(!rst_n)begin
            valid_pipe<='0;out_valid<=0;result<='0;
            ab_s1<='0;m_s2<='0;hi_s2<='0;hi_s3<='0;mp_s3<='0;
        end else begin
            valid_pipe<={valid_pipe[1:0],in_valid};out_valid<=valid_pipe[2];
            if(in_valid)ab_s1<=lhs27*rhs27;
            if(valid_pipe[0])begin
                m_s2<=lo-(lo<<26)-(lo<<S)-extra_q;
                hi_s2<={10'b0,ab_s1[53:32]};
            end
            if(valid_pipe[1])begin
                mp_s3<=m_ext+(m_ext<<26)+(m_ext<<S)+extra_p;hi_s3<=hi_s2;
            end
            if(valid_pipe[2])begin
                if(hi_s3>=mp_hi)result<=hi_s3-mp_hi;
                else result<=hi_s3+P-mp_hi;
            end
        end
    end
    // synthesis translate_off
    initial begin
        if(P!=32'd104857601 && P!=32'd69206017 && P!=32'd67239937)
            $fatal(1,"unsupported sparse Montgomery27 modulus");
        if(Q!=(32'd2-P))$fatal(1,"invalid sparse Montgomery inverse");
    end
    always @(posedge clk)if(rst_n && in_valid && (lhs>=P || rhs>=P))
        $fatal(1,"noncanonical Montgomery27 input");
    // synthesis translate_on
endmodule

files.genefer_div_recip_precision.sv:
// Exact Euclidean division using an exact W-bit reciprocal and <=27x27 products.
// MAG_W is 77 or47; |value|<2^MAG_W; base2..1e9.
// Input reciprocal=floor(2^96/base); its high MAG_W bits equal floor(2^MAG_W/base).
// Twelve stages, II=1: accepted edge k -> response after edge k+11.
// base and reciprocal stay stable for every response the caller consumes.
// Abandoned work may be quarantined by the caller during configuration setup.
module genefer_div_recip_precision #(parameter int MAG_W=77, PAYLOAD_W=1) (
    input logic clk, rst_n, in_valid,
    input logic signed [MAG_W:0] value,
    input logic [31:0] base,
    input logic [95:0] reciprocal,
    input logic [PAYLOAD_W-1:0] payload_in,
    output logic out_valid,
    output logic signed [MAG_W:0] quotient,
    output logic [31:0] remainder,
    output logic [PAYLOAD_W-1:0] payload_out
);
    localparam int LIMBS=(MAG_W+26)/27, PROD_W=2*MAG_W;
    localparam int ROW01_W=(MAG_W<54 ? MAG_W : 54)+MAG_W;
    logic [11:0] valid;
    logic [9:0] negative;
    logic [MAG_W-1:0] magnitude,estimate,estimate_d,estimate_e,estimate_f,unsigned_q;
    logic correction,negative_fraction;
    logic signed [MAG_W:0] signed_q;
    logic [31:0] signed_r,provisional_d,subtracted_r;
    logic [31:0] lows[0:6],residue_product,unsigned_r,provisional_r;
    logic [PROD_W-1:0] shifted_rows[0:LIMBS-1],product_sum,row2_d;
    logic [ROW01_W-1:0] rows01;
    wire [MAG_W-1:0] reciprocal_short=reciprocal[95-:MAG_W];
    logic [PAYLOAD_W-1:0] payloads[0:11];
    for(genvar a=0;a<LIMBS;a=a+1)begin: limb
        localparam int LW=(a==LIMBS-1) ? MAG_W-a*27 : 27;
        localparam int PAIR_BITS=MAG_W<54 ? MAG_W : 54;
        localparam int HIGH_BITS=MAG_W>54 ? MAG_W-54 : 1;
        wire [LW-1:0] digit=magnitude[a*27+:LW];
        logic [LW+PAIR_BITS-1:0] pair_lo;
        logic [LW+HIGH_BITS-1:0] high_d;
        logic [LW+MAG_W-1:0] row;
        for(genvar b=0;b<LIMBS;b=b+1)begin: product
            localparam int RW=(b==LIMBS-1) ? MAG_W-b*27 : 27;
            wire [RW-1:0] reciprocal_digit=reciprocal_short[b*27+:RW];
            logic [LW+RW-1:0] partial;
            always_ff @(posedge clk)partial<=digit*reciprocal_digit;
        end
        // Stage2: low two chunks form an exact <=54-bit reciprocal half.
        always_ff @(posedge clk)
            pair_lo<=(LW+PAIR_BITS)'(product[0].partial)+((LW+PAIR_BITS)'(product[1].partial)<<27);
        if(LIMBS==3)begin: high_product
            always_ff @(posedge clk)high_d<=product[2].partial;
        end else begin: no_high_product
            assign high_d='0;
        end
        // Stage3: exact digit times the W-bit reciprocal; unused high row is0.
        always_ff @(posedge clk)
            row<=(LW+MAG_W)'(pair_lo)+((LW+MAG_W)'(high_d)<<54);
        assign shifted_rows[a]=PROD_W'(row)<<(a*27);
    end
    // Stage4: only one wide addition. The third row receives the same delay.
    always_ff @(posedge clk)rows01<=ROW01_W'(shifted_rows[0])+ROW01_W'(shifted_rows[1]);
    if(LIMBS==3)begin: high_row
        always_ff @(posedge clk)row2_d<=shifted_rows[2];
    end else begin: no_high_row
        assign row2_d='0;
    end
    // Stage5 takes the high product after this final, single wide addition.
    assign product_sum=PROD_W'(rows01)+row2_d;
    assign out_valid=valid[11];
    assign payload_out=payloads[11];
    always_ff @(posedge clk)begin
        magnitude<=MAG_W'(value<0 ? $unsigned(-value) : $unsigned(value));
        lows[0]<=value<0 ? 32'($unsigned(-value)) : value[31:0];
        for(int j=1;j<7;j=j+1)lows[j]<=lows[j-1];
        negative<={negative[8:0],value<0};
        estimate<=product_sum[PROD_W-1:MAG_W];
        estimate_d<=estimate;
        residue_product<=estimate[31:0]*base;
        // Stage7: exact low32 provisional residue (proved less than2*base).
        provisional_r<=lows[6]-residue_product;estimate_e<=estimate_d;
        // Stage8: compare and subtract in parallel, with no wide quotient add.
        correction<=provisional_r>=base;subtracted_r<=provisional_r-base;
        provisional_d<=provisional_r;estimate_f<=estimate_e;
        // Stage9: isolated wide quotient increment and remainder selection.
        unsigned_q<=estimate_f+MAG_W'(correction);
        unsigned_r<=correction ? subtracted_r : provisional_d;
        // Stage10: sign negation separate from the Euclidean floor adjustment.
        signed_q<=negative[9] ? -$signed({1'b0,unsigned_q}) : $signed({1'b0,unsigned_q});
        negative_fraction<=negative[9] && unsigned_r!=0;
        signed_r<=negative[9] && unsigned_r!=0 ? base-unsigned_r : unsigned_r;
        // Stage11: floor, not truncation, for negative nonmultiples.
        quotient<=signed_q-$signed((MAG_W+1)'(negative_fraction));
        remainder<=signed_r;
        payloads[0]<=payload_in;
        for(int j=1;j<12;j=j+1)payloads[j]<=payloads[j-1];
    end
    always_ff @(posedge clk or negedge rst_n)
        if(!rst_n)valid<=0;else valid<={valid[10:0],in_valid};
    // synthesis translate_off
    initial if(MAG_W!=77 && MAG_W!=47)$fatal(1,"unsupported narrow magnitude width");
    always @(posedge clk)if(rst_n && in_valid && value=={1'b1,{MAG_W{1'b0}}})
        $fatal(1,"narrow divider input outside magnitude contract");
    always @(posedge clk)if(rst_n && in_valid && (base<2 || base>1000000000))
        $fatal(1,"narrow divider base outside contract");
    // synthesis translate_on
endmodule

files.genefer_stream27_blockcarry_small_cell.s:
// stream27-blockcarry shared S3/A4 primitive; SOURCE-ONLY, not native/fit qualified.
// Producer already registers y. Acceptance at this edge registers digit/carry:
// one feedback edge, II1, no input/y register and no extra carry-state register.
// Caller feeds carry_out back as carry_in, preserves base/generation coherency,
// and owns error quarantine. This cell is deliberately not a frame controller.
module genefer_stream27_blockcarry_small_cell #(
    parameter int AW=16,
    parameter int P=8,
    parameter int PAYLOAD_W=1
) (
    input logic clk,rst_n,in_valid,block_start,
    input logic [31:0] base,
    input logic signed [32:0] y,
    input logic signed [2:0] carry_in,
    input logic [PAYLOAD_W-1:0] payload_in,
    output logic out_valid,out_error,
    output logic [31:0] digit,
    output logic signed [2:0] carry_out,
    output logic [PAYLOAD_W-1:0] payload_out
);
    localparam int unsigned N=32'd1<<AW;
    localparam int unsigned K=2*N+24*P;
    // Conservative, base-independent ceil(A/base^2) bound from the adopted
    // coefficient invariant. No wide divider/quotient is in this feedback loop.
    localparam int unsigned Q=2*N+23*P;
    localparam int unsigned PROOF_MIN=(2*K+2)/3+1;
    localparam int unsigned MIN_BASE=(2*N+5)>PROOF_MIN ? (2*N+5) : PROOF_MIN;
    localparam bit PARAM_OK=AW>=5 && AW<=16 && P>=1 && P<=N/2 &&
        (P&(P-1))==0 && PAYLOAD_W>=1;
    localparam logic signed [32:0] Q_BOUND=33'(Q);
    logic signed [32:0] radix,two_radix,three_radix,four_radix;
    logic signed [32:0] y_high,total,digit_next;
    logic signed [2:0] carry_effective,carry_next;
    logic legal;

    assign radix=$signed({1'b0,base});
    assign two_radix=radix<<<1;
    assign three_radix=two_radix+radix;
    assign four_radix=radix<<<2;
    assign y_high=two_radix-33'sd2+Q_BOUND;
    assign carry_effective=block_start ? 3'sd0 : carry_in;
    assign total=y+$signed({{30{carry_effective[2]}},carry_effective});
    // Six Euclidean quotient regions: floor(total/base), NOT truncation to0.
    // All thresholds and corrections fit signed33 for every legal base<=1e9.
    always_comb begin
        if(total < -radix)begin carry_next=-3'sd2;digit_next=total+two_radix;end
        else if(total < 0)begin carry_next=-3'sd1;digit_next=total+radix;end
        else if(total < radix)begin carry_next=3'sd0;digit_next=total;end
        else if(total < two_radix)begin carry_next=3'sd1;digit_next=total-radix;end
        else if(total < three_radix)begin carry_next=3'sd2;digit_next=total-two_radix;end
        else begin carry_next=3'sd3;digit_next=total-three_radix;end
    end
    // A signed3 port is already <=3; its -4/-3 encodings are rejected even
    // at block_start. Full signed33 y and full base32 are checked before any
    // narrowing. First-block history is zero, so initial y must be in0..base-1.
    assign legal=PARAM_OK && base>=32'(MIN_BASE) && base<=32'd1000000000 &&
        carry_in>=-3'sd2 && y>=-Q_BOUND && y<=y_high &&
        (!block_start || (y>=0 && y<radix)) &&
        total>=-two_radix && total<four_radix;

    always_ff @(posedge clk or negedge rst_n)begin
        if(!rst_n)begin out_valid<=0;out_error<=0;carry_out<=0;end
        else begin
            out_valid<=in_valid && legal;
            out_error<=in_valid && !legal;
