            (row_write_req && row_write_context==1'(c) && !capture_authorized) ||
            (row_read_req && row_read_context==1'(c) && !row_authorized);
    end
    wire commit_fire=allow_access && commit_we && !denied[commit_context];
    wire capture_fire=allow_access && row_write_req && !denied[row_write_context] &&
        !(commit_fire && commit_context==row_write_context);
    wire row_fire=allow_access && row_read_req && !denied[row_read_context] &&
        !(commit_fire && commit_context==row_read_context) &&
        !(capture_fire && row_write_context==row_read_context);
    wire host_fire=allow_access && host_access && !denied[host_context] &&
        !(commit_fire && commit_context==host_context) &&
        !(capture_fire && row_write_context==host_context) &&
        !(row_fire && row_read_context==host_context);
    wire scalar_fire=host_fire && !load_we && read_en;
    wire reject_fire=allow_access && ((|denied) ||
        (commit_fire && row_write_req && commit_context==row_write_context));
    wire [LP-1:0] host_bank=host_addr[AW-1:ROW_W];
    wire [LP-1:0] commit_bank=commit_address[AW-1:ROW_W];
    logic [LP-1:0] scalar_bank_d;
    logic read_valid_d,row_valid_d,commit_ack_d,capture_ack_d,rejected_d;
    logic [31:0] ram_q[0:CONTEXTS-1][0:P-1];
    assign read_valid=allow_access && read_valid_d;
    assign row_read_valid=allow_access && row_valid_d;
    assign commit_ack=allow_access && commit_ack_d;
    assign row_write_ack=allow_access && capture_ack_d;
    assign rejected=allow_access && rejected_d;
    assign read_data=$signed({{64{ram_q[read_context][scalar_bank_d][31]}},ram_q[read_context][scalar_bank_d]});
    for(genvar b=0;b<P;b=b+1)begin: row_outputs
        assign row_read_data[b*32+:32]=ram_q[row_response_context][b];
    end
    for(genvar c=0;c<CONTEXTS;c=c+1)begin: contexts
        for(genvar b=0;b<P;b=b+1)begin: natural_blocks
            logic ram_re,ram_we;
            logic [ROW_W-1:0] ram_ra,ram_wa;
            logic [31:0] ram_w;
            always_comb begin
                ram_re=0;ram_we=0;ram_ra=0;ram_wa=0;ram_w=0;
                if(commit_fire && commit_context==1'(c))begin
                    if(commit_bank==LP'(b))begin
                        ram_we=1;ram_wa=commit_address[ROW_W-1:0];ram_w=commit_word;
                    end
                end else if(capture_fire && row_write_context==1'(c))begin
                    ram_we=1;ram_wa=row_write_address;ram_w=row_write_data[b*32+:32];
                end else if(row_fire && row_read_context==1'(c))begin
                    ram_re=1;ram_ra=row_read_address;
                end else if(host_fire && host_context==1'(c) && host_bank==LP'(b))begin
                    if(load_we)begin ram_we=1;ram_wa=host_addr[ROW_W-1:0];ram_w=write_data;end
                    else if(read_en)begin ram_re=1;ram_ra=host_addr[ROW_W-1:0];end
                end
            end
            genefer_sdp_ram32 #(.AW(ROW_W),.DEPTH(T)) image_ram (
                .clk,.rst_n,.read_en(ram_re),.write_en(ram_we),.read_addr(ram_ra),
                .write_addr(ram_wa),.write_data(ram_w),.read_data(ram_q[c][b])
            );
            // synthesis translate_off
            always @(posedge clk)if(rst_n && ram_re && ram_we)
                $fatal(1,"SHADOW_ROW_MIXED_LEAF_ACCESS");
            // synthesis translate_on
        end
    end
    // Tags/selectors own the SAME accepted E0 as the synchronous RAM q.
    always_ff @(posedge clk or negedge rst_n)begin
        if(!rst_n)begin
            read_valid_d<=0;row_valid_d<=0;commit_ack_d<=0;capture_ack_d<=0;rejected_d<=0;
            scalar_bank_d<=0;read_context<=0;read_owner<=0;
            row_response_context<=0;row_response_owner<=0;
        end else begin
            read_valid_d<=scalar_fire;row_valid_d<=row_fire;
            commit_ack_d<=commit_fire;capture_ack_d<=capture_fire;rejected_d<=reject_fire;
            if(scalar_fire)begin scalar_bank_d<=host_bank;read_context<=host_context;
                read_owner<=live_owner[host_context*OWNER_W+:OWNER_W];end
            if(row_fire)begin row_response_context<=row_read_context;row_response_owner<=row_read_owner;end
        end
    end
    // synthesis translate_off
    initial if(AW<5 || AW>16 || (P!=8 && P!=16) || CONTEXTS!=2 || OWNER_W<1 ||
        ROW_W!=AW-$clog2(P) || ROW_W<1)$fatal(1,"SHADOW_ROW_GEOMETRY");
    // synthesis translate_on
endmodule

files.genefer_stream27_canonical_image_pipe_v1:
// Required S4 canonical readback barrier; outside warm recurrence.
// Raw load is natural block order d[b*T+row], not streaming bitreverse lanes.
// Registered value boundary: three edges/digit, 9N normal / 10N special.
// Both fold/write-data and legality/write-enable consume the same value token.
// Warm recurrence, arithmetic, E0-to-E1 readback and published-image ABI unchanged.
module genefer_stream27_canonical_image_pipe_v1 #(
    parameter int AW=5,P=8,
    parameter int ROW_W=AW-$clog2(P)
) (
    input logic clk,rst_n,load_valid,begin_canonical,read_req,
    input logic [ROW_W-1:0] load_row,
    input logic [P*32-1:0] load_data,c0,c1,
    input logic [31:0] base,
    input logic [AW-1:0] read_address,
    output logic busy,done,error,image_valid,
    output logic [7:0] error_code,
    output logic [63:0] cycles,
    output logic read_valid,
    output logic [AW-1:0] read_address_out,
    output logic signed [95:0] read_data
);
    localparam int LP=$clog2(P),N=1<<AW,T=1<<ROW_W,K=2*N+24*P;
    localparam int CORR_MIN=(2*K+2)/3+1;
    localparam int BASE_MIN=(2*N+5)>CORR_MIN ? 2*N+5 : CORR_MIN;
    localparam logic [7:0] CONFLICT=1,LOAD_ORDER=2,BASE_RANGE=3,
        CORRECTION_RANGE=4,NOT_READY=5,DIGIT_RANGE=6,INTERNAL_RANGE=7;
    typedef enum logic[2:0] {IDLE,READ_WORD,VALUE_WORD,PROCESS_WORD,SPECIAL_WRITE,FAILED} state_t;
    state_t state;
    logic [ROW_W:0] loaded_count;
    logic raw_ready,read_pending;
    logic [LP-1:0] read_bank_d;
    logic [AW-1:0] read_address_d,address;
    logic [1:0] pass_index;
    logic signed [2:0] carry,fold_q;
    logic [31:0] base_reg,fold_r;
    logic signed [31:0] correction0[0:P-1],correction1[0:P-1];
    logic all_zero,all_max,next_all_zero,next_all_max;
    logic [P-1:0] ram_re,ram_we;
    logic [ROW_W-1:0] ram_ra[0:P-1],ram_wa[0:P-1];
    logic [31:0] ram_w[0:P-1],ram_q[0:P-1];
    wire [LP-1:0] bank=address[AW-1:ROW_W];
    wire [ROW_W-1:0] row=address[ROW_W-1:0];
    wire base_ok=base>=32'(BASE_MIN) && base<=32'd1000000000;
    logic load_bad,correction_bad,idle_reject,process_bad;
    logic [7:0] idle_code,process_code;
    logic signed [33:0] value,value_next,remainder,base_ext,two_base,three_base;
    logic stored_digit_bad; // Payload need not reset; PROCESS follows VALUE eligibility.
    logic signed [32:0] bound_c0,input_c0,input_c1;
    wire legal_load=rst_n && state==IDLE && !error && !idle_reject && load_valid;
    wire legal_begin=rst_n && state==IDLE && !error && !idle_reject && begin_canonical;
    wire legal_read=rst_n && state==IDLE && !error && !idle_reject && read_req;
    always_comb begin
        load_bad=0;correction_bad=0;
        bound_c0=$signed({1'b0,base})-33'sd1;
        input_c0=0;input_c1=0;
        for(int b=0;b<P;b=b+1)begin
            if(load_data[b*32+:32]>=base)load_bad=1;
            input_c0=$signed({c0[b*32+31],c0[b*32+:32]});
            input_c1=$signed({c1[b*32+31],c1[b*32+:32]});
            if(input_c0>bound_c0 || input_c0< -bound_c0 ||
               input_c1>33'(K) || input_c1< -33'(K))correction_bad=1;
        end
        idle_reject=0;idle_code=0;
        if(state==IDLE && !error)begin
            if((int'(load_valid)+int'(begin_canonical)+int'(read_req))>1 ||
               (read_pending && (load_valid || begin_canonical)))begin idle_reject=1;idle_code=CONFLICT;end
            else if(load_valid)begin
                if(!base_ok)begin idle_reject=1;idle_code=BASE_RANGE;end
                else if(load_bad)begin idle_reject=1;idle_code=DIGIT_RANGE;end
                else if((loaded_count==(ROW_W+1)'(T) && load_row!=0) ||
                    (loaded_count!=(ROW_W+1)'(T) && (ROW_W+1)'(load_row)!=loaded_count))begin
                    idle_reject=1;idle_code=LOAD_ORDER;
                end
            end else if(begin_canonical)begin
                if(!raw_ready)begin idle_reject=1;idle_code=NOT_READY;end
                else if(!base_ok)begin idle_reject=1;idle_code=BASE_RANGE;end
                else if(correction_bad)begin idle_reject=1;idle_code=CORRECTION_RANGE;end
            end else if(read_req && !image_valid)begin idle_reject=1;idle_code=NOT_READY;end
        end
    end
    // The supported profile closes -2b<=value<3b, hence five exact quotients.
    // Nonnegative Euclidean remainder for negative values, not signed truncation.
    always_comb begin
        base_ext=$signed({2'b00,base_reg});two_base=base_ext<<<1;three_base=two_base+base_ext;
        value_next=$signed({2'b00,ram_q[bank]})+$signed({{31{carry[2]}},carry});
        if(pass_index==0)begin
            if(row==0)value_next=value_next+$signed({{2{correction0[bank][31]}},correction0[bank]});
            else if(row==ROW_W'(1))value_next=value_next+$signed({{2{correction1[bank][31]}},correction1[bank]});
        end
        if(value>=two_base)begin fold_q=3'sd2;remainder=value-two_base;end
        else if(value>=base_ext)begin fold_q=3'sd1;remainder=value-base_ext;end
        else if(value>=0)begin fold_q=3'sd0;remainder=value;end
        else if(value>= -base_ext)begin fold_q=-3'sd1;remainder=value+base_ext;end
        else begin fold_q=-3'sd2;remainder=value+two_base;end
        fold_r=32'(remainder);
        next_all_zero=all_zero && remainder==0;
        next_all_max=all_max && remainder==base_ext-34'sd1;
        process_bad=0;process_code=0;
        if(stored_digit_bad)begin process_bad=1;process_code=DIGIT_RANGE;end
        else if(value< -two_base || value>=three_base || remainder<0 || remainder>=base_ext ||
            (pass_index!=0 && (fold_q< -3'sd1 || fold_q>3'sd1)) ||
            (pass_index==2 && address==AW'(N-1) && fold_q!=0 &&
             !((fold_q==3'sd1 && next_all_zero) || (fold_q== -3'sd1 && next_all_max))))begin
            process_bad=1;process_code=INTERNAL_RANGE;
        end
    end
    for(genvar b=0;b<P;b=b+1)begin: image_banks
        always_comb begin
            ram_re[b]=0;ram_we[b]=0;ram_ra[b]=0;ram_wa[b]=0;ram_w[b]=0;
            if(rst_n && !error)begin
                if(legal_load)begin ram_we[b]=1;ram_wa[b]=load_row;ram_w[b]=load_data[b*32+:32];end
                if(legal_read && read_address[AW-1:ROW_W]==LP'(b))begin
                    ram_re[b]=1;ram_ra[b]=read_address[ROW_W-1:0];
                end
                if(state==READ_WORD && bank==LP'(b))begin ram_re[b]=1;ram_ra[b]=row;end
                if(state==PROCESS_WORD && bank==LP'(b) && !process_bad)begin
                    ram_we[b]=1;ram_wa[b]=row;ram_w[b]=fold_r;
                end
                if(state==SPECIAL_WRITE && bank==LP'(b))begin
                    ram_we[b]=1;ram_wa[b]=row;ram_w[b]=address==0 ? 32'hffffffff : 32'd0;
                end
            end
        end
        genefer_sdp_ram32 #(.AW(ROW_W),.DEPTH(T)) image_ram (
            .clk,.rst_n,.read_en(ram_re[b]),.write_en(ram_we[b]),.read_addr(ram_ra[b]),
            .write_addr(ram_wa[b]),.write_data(ram_w[b]),.read_data(ram_q[b])
        );
    end
    always_ff @(posedge clk or negedge rst_n)begin
        if(!rst_n)begin
            state<=IDLE;loaded_count<=0;raw_ready<=0;read_pending<=0;
            busy<=0;done<=0;error<=0;error_code<=0;image_valid<=0;cycles<=0;
            read_valid<=0;read_address_out<=0;read_bank_d<=0;read_address_d<=0;
            base_reg<=2;address<=0;pass_index<=0;carry<=0;all_zero<=1;all_max<=1;
        end else begin
            done<=0;read_valid<=0;read_pending<=legal_read;
            if(legal_read)begin read_bank_d<=read_address[AW-1:ROW_W];read_address_d<=read_address;end
            if(read_pending && state==IDLE && image_valid && !error && !idle_reject)begin
                read_valid<=1;read_address_out<=read_address_d;
            end
            if(busy)cycles<=cycles+64'd1;
            if(idle_reject)begin
                state<=FAILED;error<=1;error_code<=idle_code;image_valid<=0;busy<=0;raw_ready<=0;read_pending<=0;
            end else case(state)
                IDLE:begin
                    if(legal_load)begin
                        image_valid<=0;
                        if(loaded_count==(ROW_W+1)'(T))begin loaded_count<=1;raw_ready<=T==1;end
                        else begin loaded_count<=loaded_count+1;raw_ready<=loaded_count==(ROW_W+1)'(T-1);end
                    end
                    if(legal_begin)begin
                        raw_ready<=0;loaded_count<=0;image_valid<=0;busy<=1;cycles<=0;
                        base_reg<=base;address<=0;pass_index<=0;carry<=0;all_zero<=1;all_max<=1;state<=READ_WORD;
                        for(int b=0;b<P;b=b+1)begin correction0[b]<=$signed(c0[b*32+:32]);correction1[b]<=$signed(c1[b*32+:32]);end
                    end
                end
                READ_WORD:state<=VALUE_WORD;
                VALUE_WORD:begin
                    value<=value_next;stored_digit_bad<=pass_index==0 && ram_q[bank]>=base_reg;
                    state<=PROCESS_WORD;
                end
                PROCESS_WORD:begin
                    if(process_bad)begin
                        state<=FAILED;error<=1;error_code<=process_code;image_valid<=0;busy<=0;read_pending<=0;
                    end else begin
                        if(pass_index==2)begin all_zero<=next_all_zero;all_max<=next_all_max;end
                        if(address==AW'(N-1))begin
                            address<=0;
                            if(pass_index<2)begin pass_index<=pass_index+1;carry<= -fold_q;state<=READ_WORD;end
                            else if(fold_q==0)begin state<=IDLE;busy<=0;done<=1;image_valid<=1;end
                            else state<=SPECIAL_WRITE;
                        end else begin address<=address+1;carry<=fold_q;state<=READ_WORD;end
                    end
                end
                SPECIAL_WRITE:begin
                    if(address==AW'(N-1))begin state<=IDLE;busy<=0;done<=1;image_valid<=1;end
                    else address<=address+1;
                end
                default:;
            endcase
        end
    end
    // Payload holds/reset eligibility separate: no stale RAM token may publish.
    always_ff @(posedge clk)if(rst_n && read_pending && state==IDLE && image_valid && !error && !idle_reject)
        read_data<=$signed({{64{ram_q[read_bank_d][31]}},ram_q[read_bank_d]});
    // synthesis translate_off
    initial if(AW<5 || AW>16 || (P!=8 && P!=16) || ROW_W!=AW-$clog2(P) || ROW_W<1)
        $fatal(1,"CANON_IMAGE_GEOMETRY");
    always @(posedge clk)if(rst_n)begin
        if(done && (!image_valid || error || busy))$fatal(1,"CANON_IMAGE_DONE_ELIGIBILITY");
        if(read_valid && (!image_valid || error))$fatal(1,"CANON_IMAGE_READ_ELIGIBILITY");
    end
    // synthesis translate_on
endmodule

files.genefer_stream27_descriptor_fifo_ff_v1.s:
// Exact depth-four descriptor ring. No added head latency or empty bypass.
// Payload is intentionally unreset; level alone qualifies head ownership.
module genefer_stream27_descriptor_fifo_ff_v1 (
 input logic clk,rst_n,clear,push,pop,
 input logic [31:0] push_index,
 input logic [7:0] push_generation,
 input logic push_double,
 output logic [31:0] head_index,
 output logic [7:0] head_generation,
 output logic head_double,
 output logic [2:0] level
);
 logic [1:0] read_pointer,write_pointer;
 (* ramstyle="logic" *) logic [40:0] descriptor[0:3];
 for(genvar slot=0;slot<4;slot=slot+1)begin: bank
  always_ff @(posedge clk)
   if(rst_n && !clear && push && write_pointer==2'(slot))
    descriptor[slot]<={push_index,push_generation,push_double};
 end
 assign {head_index,head_generation,head_double}=descriptor[read_pointer];
 always_ff @(posedge clk or negedge rst_n)begin
  if(!rst_n)begin read_pointer<=0;write_pointer<=0;level<=0;end
  else if(clear)begin read_pointer<=0;write_pointer<=0;level<=0;end
  else begin
   if(push)write_pointer<=write_pointer+2'd1;
   if(pop)read_pointer<=read_pointer+2'd1;
   case({push,pop})
    2'b10:level<=level+3'd1;
    2'b01:level<=level-3'd1;
    default:begin end
   endcase
  end
 end
 // Push/pop legality belongs to unchanged host command_ready/feed_pop.
 // Clear wins and suppresses payload writes, including malformed clear+push.
endmodule

files.genefer_sdp_ram32.sv:
// Isolated simple-dual-port RAM template for early synthesis inference.
// Reset gates accesses; it does not clear memory or reset the read register.
// Read data is registered on an enabled edge; otherwise it holds.
// Mixed-port same-address read/write is outside the caller contract.
module genefer_sdp_ram32 #(parameter int AW=13, DEPTH=1<<AW) (
    input logic clk, rst_n, read_en, write_en,
    input logic [AW-1:0] read_addr, write_addr,
    input logic [31:0] write_data,
    output logic [31:0] read_data
);
    (* ramstyle="M20K, no_rw_check" *) logic [31:0] mem [0:DEPTH-1];
    always_ff @(posedge clk) begin
        if(rst_n && read_en) read_data<=mem[read_addr];
        if(rst_n && write_en) mem[write_addr]<=write_data;
    end
    // synthesis translate_off
    always @(posedge clk) if(rst_n) begin
        if(read_en && int'(read_addr)>=DEPTH) $fatal(1,"RAM read outside depth");
        if(write_en && int'(write_addr)>=DEPTH) $fatal(1,"RAM write outside depth");
        if(read_en && write_en && read_addr==write_addr) $fatal(1,"RAM mixed-port collision");
    end
    // synthesis translate_on
endmodule

files.genefer_stream27_term_context_param_v1_c:
// Additive r17 successor: pending faults never gate current-edge transport.
// Source-only scalable correction-term producer. Four contexts per lane,
// two epoch-parity banks. Initial rows0..3 seed; row m updates row m+4.
// The product captured at edge k+4 is also bypassed to that edge's consumer:
// a RAM/register write at k+4 cannot supply a pre-edge read at k+4.
// ROOT inputs must use the exact owner/row calendar; source wrapper owns ROMs.
module genefer_stream27_term_context_param_v1_contexts_v1_storage2_v1 #(
    parameter int unsigned AW=16, LANES=16,
    parameter logic [31:0] P=32'd104857601,
    parameter logic [31:0] Q=32'd4190109697
) (
    input logic clk,rst_n,quarantine,
    input logic seed_slot,seed_start,
    input logic [26:0] seed_owner,
    input logic [1:0] seed_row,
    input logic [LANES*27-1:0] seed_coeff,seed_R_roots,
    input logic pointwise_slot,pointwise_start,
    input logic [26:0] pointwise_owner,
    input logic [AW-$clog2(LANES)-1:0] pointwise_row,
    input logic [LANES*27-1:0] next_coeff,next_seed_R_roots,
    input logic [26:0] update_R_factor,
    output logic term_slot,term_start,
    output logic [26:0] term_owner,
    output logic [AW-$clog2(LANES)-1:0] term_row,
    output logic [LANES*27-1:0] term_data,
    output logic cache_ready,
    output logic [26:0] cache_owner,
    output logic out_error,fault_pending
);
    localparam int ROW_W=AW-$clog2(LANES), LANE_W=$clog2(LANES),ROWS=1<<ROW_W,TAG_W=27+ROW_W;
    logic [LANES*27-1:0] context_data[0:1][0:3];
    logic [ROW_W-1:0] context_row[0:1][0:3];
    logic [3:0] context_valid[0:1];
    logic [26:0] bank_owner[0:1];
    logic [2:0] seed_remaining;
    logic [26:0] active_seed_owner,active_pw_owner;
    logic [ROW_W:0] pw_remaining;
    logic [ROW_W-1:0] expected_pw_row;
    logic local_bad,consumer_missing,product_owner_bad;
    logic [LANES*27-1:0] current_term;
    wire stop=quarantine || out_error;
    wire [ROW_W:0] wide_target={1'b0,pointwise_row}+(ROW_W+1)'(4);
    wire update_slot=pointwise_slot && wide_target<(ROW_W+1)'(ROWS);
    wire [ROW_W-1:0] next_row=wide_target[ROW_W-1:0];
    wire reseed=next_row[ROW_W-1-:LANE_W]!=pointwise_row[ROW_W-1-:LANE_W];
    wire product_slot,product_error,product_pending;
    wire [TAG_W-1:0] product_tag;
    wire [26:0] product_owner=product_tag[TAG_W-1:ROW_W];
    wire [ROW_W-1:0] product_row=product_tag[ROW_W-1:0];
    wire [LANES*27-1:0] product_data;
    wire pw_bank=pointwise_owner[24],prod_bank=product_owner[24],seed_bank=seed_owner[24];
    wire [1:0] pw_context=pointwise_row[1:0];
    wire bypass=product_slot && product_owner==pointwise_owner && product_row==pointwise_row;

    // Selection is independent of resulting fault/accept authority.
    always_comb begin : select_current_term
        current_term=context_data[pw_bank][pw_context];
        consumer_missing=pointwise_slot && (!context_valid[pw_bank][pw_context] ||
            bank_owner[pw_bank]!=pointwise_owner || context_row[pw_bank][pw_context]!=pointwise_row);
        if(bypass)begin current_term=product_data;consumer_missing=1'b0;end
        product_owner_bad=product_slot && bank_owner[prod_bank]!=product_owner;
    end
    always_comb begin : validate_calendar
        local_bad=consumer_missing || product_owner_bad || product_pending ||
            (seed_slot && update_slot) ||
            (seed_slot && seed_start && product_slot && seed_bank==prod_bank && seed_owner!=product_owner) ||
            (seed_slot && seed_start && pointwise_slot && seed_bank==pw_bank && seed_owner!=pointwise_owner) ||
            (seed_start && (!seed_slot || seed_remaining!=0 || seed_row!=0)) ||
